<template><div><div class="table-toolbar"><div class="toolbar-gap"><slot name="toolbar-left"/></div><div class="toolbar-gap"><el-button v-if="importable" @click="importOpen=true"><el-icon><Upload/></el-icon>导入</el-button><el-button @click="exportCurrent"><el-icon><Download/></el-icon>导出当前字段</el-button><el-button @click="settingsOpen=true"><el-icon><Operation/></el-icon>字段</el-button><el-button circle @click="$emit('refresh')"><el-icon><Refresh/></el-icon></el-button></div></div><el-table v-loading="loading" :data="rows" border stripe row-key="id" @selection-change="$emit('selection-change',$event)"><el-table-column v-if="selectable" type="selection" width="48" fixed="left"/><el-table-column v-for="column in visibleColumns" :key="column.key" :prop="column.key" :label="column.label" :width="column.width" :min-width="column.minWidth||120" :fixed="column.fixed" :sortable="column.sortable"><template #header><span class="draggable-header" draggable="true" @dragstart="dragKey=column.key" @dragover.prevent @drop="dropColumn(column.key)">⋮⋮ {{column.label}}</span></template><template #default="scope"><slot :name="`cell-${column.key}`" :row="scope.row" :value="scope.row[column.key]"><span>{{column.formatter?column.formatter(scope.row):scope.row[column.key]}}</span></slot></template></el-table-column><slot name="actions"/></el-table><div v-if="pagination" class="pagination"><el-pagination v-model:current-page="page" v-model:page-size="size" background layout="total, sizes, prev, pager, next, jumper" :total="pagination.total" :page-sizes="[10,20,50,100]" @change="$emit('page-change',{pageIndex:page,pageSize:size})"/></div><LemonColumnSettings v-model="settingsOpen" :columns="columnsWithPreferences" @apply="apply" @reset="reset"/><LemonImportDialog v-model="importOpen" @submit="$emit('import',$event)"/></div></template>
<script setup lang="ts" generic="T extends Record<string, any>">import {computed,ref,toRef,watch} from 'vue';import type {LemonColumn} from '@/types/table';import {useTablePreferences} from '@/composables/use-table-preferences';import {downloadCsv} from '@/utils/csv';import LemonColumnSettings from './LemonColumnSettings.vue';import LemonImportDialog from './LemonImportDialog.vue';const props=withDefaults(defineProps<{tableKey:string;rows:T[];columns:LemonColumn<T>[];loading?:boolean;selectable?:boolean;importable?:boolean;pagination?:{pageIndex:number;pageSize:number;total:number};exportName?:string}>(),{loading:false,selectable:false,importable:false,exportName:'列表'});defineEmits<{refresh:[];import:[Record<string,string>[]];'page-change':[{pageIndex:number;pageSize:number}];'selection-change':[T[]]}>();const settingsOpen=ref(false),importOpen=ref(false),dragKey=ref('');const source=toRef(props,'columns');const {columns:columnsWithPreferences,setColumns,reset}=useTablePreferences<T>(props.tableKey,source);const visibleColumns=computed(()=>columnsWithPreferences.value.filter(c=>c.visible!==false));const page=ref(props.pagination?.pageIndex||1),size=ref(props.pagination?.pageSize||20);watch(()=>props.pagination,v=>{if(v){page.value=v.pageIndex;size.value=v.pageSize}},{deep:true});function apply(cols:LemonColumn<T>[]){setColumns(cols)}function dropColumn(target:string){const list=columnsWithPreferences.value.map(c=>({...c}));const from=list.findIndex(c=>c.key===dragKey.value),to=list.findIndex(c=>c.key===target);if(from<0||to<0||from===to)return;const [item]=list.splice(from,1);list.splice(to,0,item);setColumns(list);dragKey.value='';}function exportCurrent(){const cols=visibleColumns.value.filter(c=>c.exportable!==false);downloadCsv(`${props.exportName}-${new Date().toISOString().slice(0,10)}.csv`,cols.map(c=>c.label),props.rows.map(row=>cols.map(c=>c.formatter?c.formatter(row):row[c.key])));}</script>
<style scoped>.table-toolbar{display:flex;justify-content:space-between;align-items:center;margin-bottom:12px;gap:12px}.pagination{display:flex;justify-content:flex-end;margin-top:16px}</style>
